export type CreateInput<T extends BaseRecord> = Omit<
  T,
  "id" | "createdAt" | "updatedAt"
>;
export type UpdateInput<T extends BaseRecord> = Partial<T>;

export interface Repository<T extends BaseRecord> {
  create(input: CreateInput<T>): Promise<T>;
  get(id: string): Promise<T | undefined>;
  list(): Promise<T[]>;
  update(id: string, patch: UpdateInput<T>): Promise<T>;
  delete(id: string): Promise<void>;
  findByIndex(indexName: string, query: IDBValidKey | IDBKeyRange): Promise<T[]>;
}

export interface RepositoryDependencies {
  now?: () => string;
  createId?: () => string;
}

type Validator<T extends BaseRecord> = (record: T) => void;

function defaultCreateId(): string {
  return crypto.randomUUID();
}

function defaultNow(): string {
  return new Date().toISOString();
}

function assertIsoTimestamp(value: string, field: string): void {
  if (Number.isNaN(Date.parse(value))) {
    throw new Error(`Invalid ${field}: expected an ISO timestamp`);
  }
}

function nextTimestamp(candidate: string, previous: string): string {
  assertIsoTimestamp(candidate, "updatedAt");
  if (candidate > previous) {
    return candidate;
  }
  return new Date(Date.parse(previous) + 1).toISOString();
}

function includes<T extends string>(values: readonly T[], value: unknown): value is T {
  return typeof value === "string" && values.includes(value as T);
}

function validateBase(record: BaseRecord): void {
  if (!record.id) {
    throw new Error("Invalid record id");
  }
  assertIsoTimestamp(record.createdAt, "createdAt");
  assertIsoTimestamp(record.updatedAt, "updatedAt");
}

function validateResume(record: Resume): void {
  if (!includes(RESUME_STATUSES, record.status)) {
    throw new Error("Invalid Resume.status");
  }
}

function validateStage(record: Stage): void {
  if (!includes(STAGE_KINDS, record.kind)) {
    throw new Error("Invalid Stage.kind");
  }
}

function validateTimezone(timezone: string): void {
  try {
    new Intl.DateTimeFormat("en", { timeZone: timezone }).format();
  } catch {
    throw new Error("Invalid Interview.timezone");
  }
}

function validateInterview(record: Interview): void {
  if (!includes(INTERVIEW_STATUSES, record.status)) {
    throw new Error("Invalid Interview.status");
  }
  assertIsoTimestamp(record.startsAt, "Interview.startsAt");
  if (record.endsAt !== undefined) {
    assertIsoTimestamp(record.endsAt, "Interview.endsAt");
  }
  validateTimezone(record.timezone);
}

class IndexedDbRepository<T extends BaseRecord> implements Repository<T> {
  readonly #database: IDBDatabase;
  readonly #storeName: StoreName;
  readonly #now: () => string;
  readonly #createId: () => string;
  readonly #validate?: Validator<T>;

  constructor(
    database: IDBDatabase,
    storeName: StoreName,
    dependencies: Required<RepositoryDependencies>,
    validate?: Validator<T>,
  ) {
    this.#database = database;
    this.#storeName = storeName;
    this.#now = dependencies.now;
    this.#createId = dependencies.createId;
    this.#validate = validate;
  }

  async create(input: CreateInput<T>): Promise<T> {
    const timestamp = this.#now();
    assertIsoTimestamp(timestamp, "createdAt");
    const record = {
      ...input,
      id: this.#createId(),
      createdAt: timestamp,
      updatedAt: timestamp,
    } as T;
    validateBase(record);
    this.#validate?.(record);

    await runTransaction(this.#database, this.#storeName, "readwrite", (transaction) =>
      requestToPromise(transaction.objectStore(this.#storeName).add(record)),
    );
    return record;
  }

  get(id: string): Promise<T | undefined> {
    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
      requestToPromise<T | undefined>(
        transaction.objectStore(this.#storeName).get(id),
      ),
    );
  }

  list(): Promise<T[]> {
    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
      requestToPromise<T[]>(transaction.objectStore(this.#storeName).getAll()),
    );
  }

  async update(id: string, patch: UpdateInput<T>): Promise<T> {
    return runTransaction(this.#database, this.#storeName, "readwrite", async (transaction) => {
      const store = transaction.objectStore(this.#storeName);
      const existing = await requestToPromise<T | undefined>(store.get(id));
      if (!existing) {
        throw new Error(`Record not found: ${id}`);
      }

      const updated = {
        ...existing,
        ...patch,
        id: existing.id,
        createdAt: existing.createdAt,
        updatedAt: nextTimestamp(this.#now(), existing.updatedAt),
      };
      validateBase(updated);
      this.#validate?.(updated);
      await requestToPromise(store.put(updated));
      return updated;
    });
  }

  async delete(id: string): Promise<void> {
    await runTransaction(this.#database, this.#storeName, "readwrite", (transaction) =>
      requestToPromise(transaction.objectStore(this.#storeName).delete(id)),
    );
  }

  findByIndex(
    indexName: string,
    query: IDBValidKey | IDBKeyRange,
  ): Promise<T[]> {
    return runTransaction(this.#database, this.#storeName, "readonly", (transaction) =>
      requestToPromise<T[]>(
        transaction.objectStore(this.#storeName).index(indexName).getAll(query),
      ),
    );
  }
}

export interface DomainRepositories {
  resumes: Repository<Resume>;
  resumeTexts: Repository<ResumeText>;
  jobDescriptions: Repository<JobDescription>;
  jobDescriptionTexts: Repository<JobDescriptionText>;
  applications: Repository<Application>;
  resumeUsageHistory: Repository<ResumeUsageHistory>;
  stages: Repository<Stage>;
  applicationTimelineEvents: Repository<ApplicationTimelineEvent>;
  interviews: Repository<Interview>;
  interviewReviews: Repository<InterviewReview>;
  analysisResults: Repository<AnalysisResult>;
  aiConversations: Repository<AiConversation>;
}

export function createRepositories(
  database: IDBDatabase,
  dependencies: RepositoryDependencies = {},
): DomainRepositories {
  const resolvedDependencies: Required<RepositoryDependencies> = {
    now: dependencies.now ?? defaultNow,
    createId: dependencies.createId ?? defaultCreateId,
  };
  const repository = <T extends BaseRecord>(
    storeName: StoreName,
    validate?: Validator<T>,
  ): Repository<T> =>
    new IndexedDbRepository(database, storeName, resolvedDependencies, validate);

  return {
    resumes: repository(STORE_NAMES.resumes, validateResume),
    resumeTexts: repository(STORE_NAMES.resumeTexts),
    jobDescriptions: repository(STORE_NAMES.jobDescriptions),
    jobDescriptionTexts: repository(STORE_NAMES.jobDescriptionTexts),
    applications: repository(STORE_NAMES.applications),
    resumeUsageHistory: repository(STORE_NAMES.resumeUsageHistory),
    stages: repository(STORE_NAMES.stages, validateStage),
    applicationTimelineEvents: repository(
      STORE_NAMES.applicationTimelineEvents,
    ),
    interviews: repository(STORE_NAMES.interviews, validateInterview),
    interviewReviews: repository(STORE_NAMES.interviewReviews),
    analysisResults: repository(STORE_NAMES.analysisResults),
    aiConversations: repository(STORE_NAMES.aiConversations),
  };
}
import {
  INTERVIEW_STATUSES,
  RESUME_STATUSES,
  STAGE_KINDS,
} from "./types";
import { STORE_NAMES, type StoreName } from "./schema";

type StoredRecord = Record<string, unknown>;

const EPOCH = "1970-01-01T00:00:00.000Z";

const DEFAULTS: Partial<Record<StoreName, StoredRecord>> = {
  resumes: { tags: [], note: "", status: "needs-review" },
  jobDescriptions: { textSource: "pasted" },
  applications: { jobType: "other", workMode: "unknown", priority: 0 },
  resumeUsageHistory: {},
  stages: { kind: "normal" },
  applicationTimelineEvents: { note: "" },
  interviews: { status: "scheduled", reminders: [], note: "" },
  interviewReviews: {
    questions: [],
    goodAnswers: "",
    weakAnswers: "",
    observedSignals: "",
    salaryDiscussion: "",
    nextStep: "",
    privateNote: "",
  },
  analysisResults: {
    mode: "local",
    coverage: { overall: 0, required: 0, preferred: 0 },
    matchedKeywords: [],
    weakMatches: [],
    missingKeywords: [],
    evidence: [],
    uncertainItems: [],
    recommendations: [],
  },
  aiConversations: { messages: [] },
};

function addMissingDefaults(record: StoredRecord, defaults: StoredRecord): boolean {
  let changed = false;

  for (const [key, value] of Object.entries(defaults)) {
    if (record[key] === undefined) {
      record[key] = value;
      changed = true;
    }
  }

  const createdAt =
    record.createdAt ?? record.uploadedAt ?? record.usedAt ?? record.startsAt ?? EPOCH;
  if (record.createdAt === undefined) {
    record.createdAt = createdAt;
    changed = true;
  }
  if (record.updatedAt === undefined) {
    record.updatedAt = createdAt;
    changed = true;
  }

  return changed;
}

function hasValue<T extends string>(values: readonly T[], value: unknown): value is T {
  return typeof value === "string" && values.includes(value as T);
}

function validateMigratedRecord(storeName: StoreName, record: StoredRecord): void {
  if (
    storeName === STORE_NAMES.resumes &&
    !hasValue(RESUME_STATUSES, record.status)
  ) {
    throw new Error("Invalid Resume.status in migrated record");
  }
  if (
    storeName === STORE_NAMES.interviews &&
    !hasValue(INTERVIEW_STATUSES, record.status)
  ) {
    throw new Error("Invalid Interview.status in migrated record");
  }
  if (storeName === STORE_NAMES.stages && !hasValue(STAGE_KINDS, record.kind)) {
    throw new Error("Invalid Stage.kind in migrated record");
  }
}

function migrateStore(
  transaction: IDBTransaction,
  storeName: StoreName,
  defaults: StoredRecord,
): void {
  const request = transaction.objectStore(storeName).openCursor();

  request.addEventListener("success", () => {
    const cursor = request.result;
    if (!cursor) {
      return;
    }

    const record = cursor.value as StoredRecord;
    const changed = addMissingDefaults(record, defaults);
    validateMigratedRecord(storeName, record);
    if (changed) {
      cursor.update(record);
    }
    cursor.continue();
  });
}

export function runMigrations(
  transaction: IDBTransaction,
  oldVersion: number,
): void {
  if (oldVersion === 0 || oldVersion >= 2) {
    return;
  }

  for (const [storeName, defaults] of Object.entries(DEFAULTS) as Array<
    [StoreName, StoredRecord]
  >) {
    if (transaction.db.objectStoreNames.contains(storeName)) {
      migrateStore(transaction, storeName, defaults);
    }
  }
}
import {
  DATABASE_NAME,
  DATABASE_VERSION,
  ensureSchema,
  type StoreName,
} from "./schema";
import { runMigrations } from "./migrations";

export interface OpenDatabaseOptions {
  name?: string;
  version?: number;
  factory?: IDBFactory;
}

export function requestToPromise<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.addEventListener("success", () => resolve(request.result));
    request.addEventListener("error", () =>
      reject(request.error ?? new Error("IndexedDB request failed")),
    );
  });
}

export function transactionToPromise(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.addEventListener("complete", () => resolve());
    transaction.addEventListener("abort", () =>
      reject(transaction.error ?? new Error("IndexedDB transaction aborted")),
    );
    transaction.addEventListener("error", () =>
      reject(transaction.error ?? new Error("IndexedDB transaction failed")),
    );
  });
}

export async function runTransaction<T>(
  database: IDBDatabase,
  storeNames: StoreName | readonly StoreName[],
  mode: IDBTransactionMode,
  operation: (transaction: IDBTransaction) => T | Promise<T>,
): Promise<T> {
  const transaction = database.transaction(storeNames, mode);
  const completion = transactionToPromise(transaction);

  try {
    const result = await operation(transaction);
    await completion;
    return result;
  } catch (error) {
    try {
      transaction.abort();
    } catch {
      // The transaction may already have completed or aborted.
    }
    await completion.catch(() => undefined);
    throw error;
  }
}

export function openCareerDatabase(
  options: OpenDatabaseOptions = {},
): Promise<IDBDatabase> {
  const factory = options.factory ?? indexedDB;
  const name = options.name ?? DATABASE_NAME;
  const version = options.version ?? DATABASE_VERSION;

  return new Promise((resolve, reject) => {
    const request = factory.open(name, version);
    let upgradeError: unknown;

    request.addEventListener("upgradeneeded", (event) => {
      try {
        const transaction = request.transaction;
        if (!transaction) {
          throw new Error("IndexedDB upgrade transaction is unavailable");
        }
        ensureSchema(request.result, transaction);
        runMigrations(transaction, event.oldVersion);
      } catch (error) {
        upgradeError = error;
        request.transaction?.abort();
      }
    });
    request.addEventListener("success", () => resolve(request.result));
    request.addEventListener("error", () =>
      reject(
        upgradeError ?? request.error ?? new Error("Unable to open IndexedDB"),
      ),
    );
    request.addEventListener("blocked", () =>
      reject(new Error(`IndexedDB upgrade is blocked for ${name}`)),
    );
  });
}

export function deleteCareerDatabase(
  name = DATABASE_NAME,
  factory: IDBFactory = indexedDB,
): Promise<void> {
  return new Promise((resolve, reject) => {
    const request = factory.deleteDatabase(name);
    request.addEventListener("success", () => resolve());
    request.addEventListener("error", () =>
      reject(request.error ?? new Error(`Unable to delete IndexedDB ${name}`)),
    );
    request.addEventListener("blocked", () =>
      reject(new Error(`IndexedDB deletion is blocked for ${name}`)),
    );
  });
}

